      {
        "id": 18,
        "start": 54.2,
        "end": 56.28,
        "duration": 2.08,
        "text": "- Wir sehen uns, wenn ich wiederkomme, okay?"
      },
      {
        "id": 19,
        "start": 56.32,
        "end": 57.32,
        "duration": 1.0,
        "text": "- Okay!"
      }
